```python
from collections import defaultdict

def ford_fulkerson(graph, source, sink):
    n = len(graph)
    flow = [0] * n
    potential = [float('-inf')] * n

    def augment_flow(u, v, flow_value):
        nonlocal potential

        if u == v:
            return flow_value

        for w, cap in graph[u]:
            if cap > flow[u] and potential[w] >= potential[u]:
                delta_flow = augment_flow(w, u, min(flow_value, cap - flow[u]))
                flow[u] += delta_flow
                flow[w] -= delta_flow
                return delta_flow

        return 0

    while True:
        min_cut_flow = float('inf')
        for u in range(n):
            for v in range(n):
                if u != v and potential[u] >= potential[v]:
                    min_cut_flow = min(min_cut_flow, augment_flow(u, v, float('inf')))

        if min_cut_flow == float('inf'):
            break

        for u in range(n):
            potential[u] += min_cut_flow

    return sum(flow[u] for u in range(n) if u != sink)

# Example usage
graph = [[0, 1, 16], [0, 2, 13], [1, 2, 10], [1, 3, 12], [2, 1, 4], [2, 4, 14], [3, 2, 9], [3, 5, 20], [4, 3, 7], [4, 5, 4], 0, 5]
source, sink = 0, 5
print(ford_fulkerson(graph, source, sink))  # Output: 23
```

This program first initializes a potential array to negative infinity and a flow array to zero. Then, it uses a recursive function `augment_flow` to find the maximum flow from the source to the sink. The potential array is updated after each call to `augment_flow` to ensure that the algorithm always finds a maximum flow. Finally, the minimum cut value is calculated by summing up the flow values of all nodes except the sink.
